solution:
function runLRUCache(capacity, operations) {
  const map = new Map();
  const results = [];
  for (const op of operations) {
    const [action, key, val] = op;
    if (action === 'put') {
      if (map.has(key)) {
        map.delete(key);
      } else if (map.size >= capacity) {
        const oldest = map.keys().next().value;
        map.delete(oldest);
      }
      map.set(key, val);
    } else if (action === 'get') {
      if (!map.has(key)) {
        results.push(-1);
      } else {
        const value = map.get(key);
        map.delete(key);
        map.set(key, value);
        results.push(value);
      }
    }
  }
  return results;
}

